// Renders the skill cards from data/skills.js (generated by tools/build.py) and wires the
// copy buttons and site-config links. Plain script, no dependencies, works from file:// too.
(function () {
  "use strict";

  var site = (window.EGM && window.EGM.site) || {};
  var skills = (window.EGM && window.EGM.skills) || [];

  function text(el, value) {
    if (value) el.textContent = value;
  }

  // Fill text and link targets from site.json, so the repo URL is configured in one place.
  document.querySelectorAll("[data-site]").forEach(function (el) {
    text(el, site[el.getAttribute("data-site")]);
  });
  document.querySelectorAll("[data-site-href]").forEach(function (el) {
    var base = site[el.getAttribute("data-site-href")];
    if (!base) return;
    el.setAttribute("href", base + (el.getAttribute("data-site-suffix") || ""));
  });

  function card(skill) {
    var article = document.createElement("article");
    article.className = "card skill " + skill.group.toLowerCase();

    var group = document.createElement("span");
    group.className = "tag";
    group.textContent = skill.group;

    var title = document.createElement("h3");
    title.textContent = skill.title;

    var command = document.createElement("code");
    command.textContent = skill.command;

    var summary = document.createElement("p");
    summary.textContent = skill.summary;

    var details = document.createElement("details");
    var summaryLine = document.createElement("summary");
    summaryLine.textContent = "Full description";
    var full = document.createElement("p");
    full.className = "full";
    full.textContent = skill.description;
    var source = document.createElement("p");
    source.className = "source";
    source.textContent = "Defined in " + skill.source;
    details.appendChild(summaryLine);
    details.appendChild(full);
    details.appendChild(source);

    article.appendChild(group);
    article.appendChild(title);
    article.appendChild(command);
    article.appendChild(summary);
    article.appendChild(details);
    return article;
  }

  var grid = document.getElementById("skill-grid");
  if (grid && skills.length) {
    grid.textContent = "";
    skills.forEach(function (skill) {
      grid.appendChild(card(skill));
    });
  }

  // Copy buttons. The text comes from the page so the button always copies what is shown.
  function copyText(value) {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(value);
    }
    var area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "absolute";
    area.style.left = "-9999px";
    document.body.appendChild(area);
    area.select();
    var ok = document.execCommand("copy");
    document.body.removeChild(area);
    return ok ? Promise.resolve() : Promise.reject(new Error("copy failed"));
  }

  document.querySelectorAll("[data-copy]").forEach(function (button) {
    button.addEventListener("click", function () {
      var which = button.getAttribute("data-copy");
      var value = which === "local" ? site.local_install_command : site.install_command;
      var original = button.textContent;
      copyText(value).then(function () {
        button.textContent = "Copied";
      }, function () {
        button.textContent = "Select and copy";
      }).then(function () {
        setTimeout(function () { button.textContent = original; }, 1600);
      });
    });
  });
})();
